"use client";

import "./native-select.css";
import { ChevronsUpDown } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/cn";

import { NativeSelectContext, useNativeSelectContext } from "./native-select.context";
import { nativeSelectVariants, type NativeSelectVariants } from "./native-select.variants";

export type NativeSelectProps = NativeSelectVariants &
  Omit<React.SelectHTMLAttributes<HTMLSelectElement>, "size"> & {
    children?: React.ReactNode;
    icon?: React.ReactNode;
  };

export const NativeSelectRoot = ({
  children,
  className,
  icon,
  size,
  variant,
  ...props
}: NativeSelectProps) => {
  const slots = nativeSelectVariants({ size, variant });

  return (
    <NativeSelectContext.Provider value={{ slots }}>
      <div className={slots.root()}>
        <select className={cn(slots.select(), className)} {...props}>
          {children}
        </select>
        <span className={slots.icon()}>
          {icon ?? <ChevronsUpDown />}
        </span>
      </div>
    </NativeSelectContext.Provider>
  );
};

export type NativeSelectOptionProps = React.OptionHTMLAttributes<HTMLOptionElement>;

export const NativeSelectOption = ({ className, ...props }: NativeSelectOptionProps) => {
  const { slots } = useNativeSelectContext();
  return <option className={cn(slots.option(), className)} {...props} />;
};

export type NativeSelectOptGroupProps = React.OptgroupHTMLAttributes<HTMLOptGroupElement>;

export const NativeSelectOptGroup = ({ className, ...props }: NativeSelectOptGroupProps) => {
  const { slots } = useNativeSelectContext();
  return <optgroup className={cn(slots.optgroup(), className)} {...props} />;
};

export const NativeSelect = NativeSelectRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const nativeSelectVariants = tv({
  slots: {
    root: "native-select__root",
    select: "native-select",
    icon: "native-select__icon",
    option: "native-select__option",
    optgroup: "native-select__optgroup",
  },
  variants: {
    size: {
      sm: {
        root: "native-select__root--sm",
        select: "native-select--sm",
        icon: "native-select__icon--sm",
      },
      md: {
        root: "native-select__root--md",
        select: "native-select--md",
        icon: "native-select__icon--md",
      },
      lg: {
        root: "native-select__root--lg",
        select: "native-select--lg",
        icon: "native-select__icon--lg",
      },
    },
    variant: {
      default: {
        select: "native-select--default",
      },
      outline: {
        select: "native-select--outline",
      },
    },
  },
  defaultVariants: {
    size: "md",
    variant: "default",
  },
});

export type NativeSelectVariants = VariantProps<typeof nativeSelectVariants>;

"use client";

import { createContext, useContext } from "react";

import { nativeSelectVariants } from "./native-select.variants";

export type NativeSelectContext = {
  slots: ReturnType<typeof nativeSelectVariants>;
};

export const NativeSelectContext = createContext<NativeSelectContext | null>(null);

export const useNativeSelectContext = () => {
  const context = useContext(NativeSelectContext);
  return context ?? { slots: nativeSelectVariants() };
};

.native-select__root {
  @apply relative flex w-full items-center;
}

.native-select {
  @apply border-input bg-background text-foreground placeholder:text-muted-foreground focus-visible:outline-ring data-invalid:border-destructive data-invalid:focus-visible:outline-destructive appearance-none flex w-full rounded-md border py-1 pl-3 pr-8 text-sm shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50 cursor-pointer;
}

.native-select--sm {
  @apply h-8 pl-2.5 pr-7 text-xs;
}

.native-select--md {
  @apply h-9 pl-3 pr-8 text-sm;
}

.native-select--lg {
  @apply h-10 pl-3.5 pr-9 text-base;
}

.native-select__icon {
  @apply text-muted-foreground pointer-events-none absolute right-2.5 top-1/2 h-4 w-4 -translate-y-1/2 shrink-0 transition-transform duration-200;
}

.native-select__icon svg {
  @apply h-full w-full;
}

.native-select__icon--sm {
  @apply right-2 h-3.5 w-3.5;
}

.native-select__icon--md {
  @apply right-2.5 h-4 w-4;
}

.native-select__icon--lg {
  @apply right-3 h-5 w-5;
}

.native-select__option {
  @apply bg-background text-foreground;
}

.native-select__optgroup {
  @apply font-semibold;
}

import {
  NativeSelect as NativeSelectRootComponent,
  NativeSelectOptGroup,
  NativeSelectOption,
  NativeSelectRoot,
} from "./native-select";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/native-select/content.md
 */
export const NativeSelect = Object.assign(NativeSelectRootComponent, {
  OptGroup: NativeSelectOptGroup,
  Option: NativeSelectOption,
  Root: NativeSelectRoot,
});

export {
  NativeSelectOptGroup,
  NativeSelectOption,
  NativeSelectRoot,
};

export type {
  NativeSelectOptGroupProps,
  NativeSelectOptionProps,
  NativeSelectProps,
} from "./native-select";
export { NativeSelectContext, useNativeSelectContext } from "./native-select.context";
export { type NativeSelectVariants, nativeSelectVariants } from "./native-select.variants";
